import React from 'react';
import Link from 'next/link';
import { Globe, Clock, Activity, ExternalLink, Trash2 } from 'lucide-react';
import { Card } from './ui/Card';
import { StatusBadge } from './StatusBadge';
import { formatRelativeTime } from '@/lib/utils';
import type { MonitoredSiteWithLatestCheck } from '@pingwatch/shared';

interface SiteCardProps {
  site: MonitoredSiteWithLatestCheck;
  onDelete?: (siteId: string) => void;
  isDeleting?: boolean;
}

export function SiteCard({ site, onDelete, isDeleting }: SiteCardProps) {
  const latestCheck = site.latest_check;
  const isDown = site.last_status === 'down';

  return (
    <Card
      className={`group relative hover:border-[#8B949E] transition-all duration-200 flex flex-col justify-between ${
        isDown ? 'border-[#FF4D4F]/50 shadow-[0_0_15px_rgba(255,77,79,0.15)]' : ''
      }`}
    >
      <div>
        {/* Header: Name + Status Badge */}
        <div className="flex items-start justify-between gap-3 mb-3">
          <div className="min-w-0 flex-1">
            <Link
              href={`/dashboard/sites/${site.id}`}
              className="text-base font-semibold text-white group-hover:text-[#00FF87] transition-colors truncate block"
            >
              {site.name}
            </Link>
            <div className="flex items-center gap-1.5 mt-1 text-xs text-[#8B949E] font-mono truncate">
              <Globe className="h-3.5 w-3.5 flex-shrink-0" />
              <span className="truncate">{site.url}</span>
              <a
                href={site.url}
                target="_blank"
                rel="noreferrer"
                onClick={(e) => e.stopPropagation()}
                className="hover:text-white transition-colors"
              >
                <ExternalLink className="h-3 w-3" />
              </a>
            </div>
          </div>
          <StatusBadge status={site.last_status} />
        </div>

        {/* Metrics Row */}
        <div className="grid grid-cols-2 gap-3 py-3 border-y border-[#30363D] my-3">
          <div className="flex flex-col">
            <span className="text-[11px] text-[#8B949E] uppercase tracking-wider flex items-center gap-1">
              <Activity className="h-3 w-3" /> Response Time
            </span>
            <span className="text-sm font-mono font-medium text-white mt-1">
              {latestCheck?.response_ms !== undefined && latestCheck?.response_ms !== null
                ? `${latestCheck.response_ms} ms`
                : '—'}
            </span>
          </div>

          <div className="flex flex-col">
            <span className="text-[11px] text-[#8B949E] uppercase tracking-wider flex items-center gap-1">
              <Clock className="h-3 w-3" /> Checked
            </span>
            <span className="text-sm font-mono text-white mt-1">
              {formatRelativeTime(site.last_checked_at)}
            </span>
          </div>
        </div>
      </div>

      {/* Footer / Actions */}
      <div className="flex items-center justify-between pt-1">
        <div className="text-xs text-[#8B949E]">
          Interval: <span className="font-mono text-white">{site.check_interval_s}s</span>
        </div>

        <div className="flex items-center gap-2">
          {onDelete && (
            <button
              type="button"
              onClick={(e) => {
                e.preventDefault();
                if (confirm(`Stop monitoring and delete "${site.name}"?`)) {
                  onDelete(site.id);
                }
              }}
              disabled={isDeleting}
              className="p-1.5 text-[#8B949E] hover:text-[#FF4D4F] hover:bg-[#FF4D4F]/10 rounded transition-colors"
              title="Delete Site"
            >
              <Trash2 className="h-4 w-4" />
            </button>
          )}

          <Link
            href={`/dashboard/sites/${site.id}`}
            className="text-xs font-semibold text-[#00FF87] hover:underline flex items-center gap-1"
          >
            View Details &rarr;
          </Link>
        </div>
      </div>
    </Card>
  );
}
